    // V094_REQUEST_NOTIFICATION_REGRESSION: requesting supervision creates a notification
    // even if the student has NO Project. The recipient is the requested lecturer only.
    [Fact]
    public async Task PendingLecturerRequest_NotificationIsDeliveredOnlyToLecturer_AndIsIdempotent()
    {
        using var app = new TestApp();
        var requestId = Guid.NewGuid();
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            await db.Database.EnsureCreatedAsync();
            AddUser(db, StudentA, "student-a@v09.test", RoleIds.Student);
            AddUser(db, LecturerA, "lecturer-a@v09.test", RoleIds.Lecturer);
            AddUser(db, LecturerB, "lecturer-b@v09.test", RoleIds.Lecturer);
            db.LecturerRequests.Add(new LecturerRequest
            {
                Id = requestId, StudentUserId = StudentA, LecturerUserId = LecturerA,
                TopicId = Guid.NewGuid(), RegistrationPeriodId = Guid.NewGuid(),
                IsCombined = true, DraftTitle = "Đề tài kiểm thử thông báo",
                Status = RequestStatus.PENDING
            });
            await db.SaveChangesAsync();
        }
        using var lecturer = await Login(app, "lecturer-a@v09.test");
        using var otherLecturer = await Login(app, "lecturer-b@v09.test");
        using var student = await Login(app, "student-a@v09.test");
        const string path = "/api/v1/v08/notifications";
        using (var result = (await lecturer.GetFromJsonAsync<JsonDocument>(path))!)
        {
            var rows = result.RootElement.GetProperty("items").EnumerateArray().ToArray();
            var notice = Assert.Single(rows.Where(x => x.GetProperty("type").GetString() == $"V08:REQ:{requestId:N}"));
            Assert.Contains("Đề tài kiểm thử thông báo", notice.GetProperty("message").GetString());
            Assert.Equal($"/lecturer-requests?requestId={requestId:D}",
                notice.GetProperty("targetUrl").GetString());
        }
        using (var retry = (await lecturer.GetFromJsonAsync<JsonDocument>(path))!)
            Assert.Single(retry.RootElement.GetProperty("items").EnumerateArray());
        using (var outsider = (await otherLecturer.GetFromJsonAsync<JsonDocument>(path))!)
            Assert.Empty(outsider.RootElement.GetProperty("items").EnumerateArray());
        using (var studentView = (await student.GetFromJsonAsync<JsonDocument>(path))!)
            Assert.Empty(studentView.RootElement.GetProperty("items").EnumerateArray());
    }

