                TopicId = Guid.NewGuid(), RegistrationPeriodId = Guid.NewGuid(),
                Status = RequestStatus.OFFERED, DraftTitle = "Topic accepted"
            });
            db.AuditEntries.Add(new AuditEntry
            {
                ActorUserId = LecturerA, EntityName = "LecturerRequest",
